package cn.balltv.portal;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.io.*;
public class PreviewRegressionTest {
 int[] sample(int index)throws Exception{try(InputStream in=getClass().getResourceAsStream("/basketball-preview-regression.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONArray a=new JSONArray(out.toString("UTF-8")).getJSONArray(index);int[] p=new int[a.length()];for(int i=0;i<p.length;i++)p[i]=a.getInt(i);return p;}}
 @Test public void grayNbaFloorWithBlueCourtLinesDoesNotLoseItsPreview()throws Exception{try(InputStream in=getClass().getResourceAsStream("/gray-court.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONArray a=new JSONArray(out.toString("UTF-8"));int[] pixels=new int[a.length()];for(int i=0;i<pixels.length;i++)pixels[i]=a.getInt(i);assertTrue(SportsPreview.acceptable(pixels,"basketball"));}}
 @Test public void palePinkNbaFloorDoesNotLoseItsPreview()throws Exception{try(InputStream in=getClass().getResourceAsStream("/pink-court.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONArray a=new JSONArray(out.toString("UTF-8"));int[] pixels=new int[a.length()];for(int i=0;i<pixels.length;i++)pixels[i]=a.getInt(i);assertTrue(SportsPreview.acceptable(pixels,"basketball"));}}
 @Test public void realGreenKeyBasketballCourtDoesNotLoseItsPreview()throws Exception{try(InputStream in=getClass().getResourceAsStream("/green-key-court.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONArray a=new JSONArray(out.toString("UTF-8").replace("\uFEFF",""));int[] pixels=new int[a.length()];for(int i=0;i<pixels.length;i++)pixels[i]=a.getInt(i);assertTrue(SportsPreview.acceptable(pixels,"basketball"));}}
 @Test public void observedBasketballPromotionPosterIsWithheld()throws Exception{assertFalse(SportsPreview.acceptable(sample(0),"basketball"));}
 @Test public void observedWoodenCourtStillPasses()throws Exception{assertTrue(SportsPreview.acceptable(sample(1),"basketball"));}
}
